using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static class NoticeTests
 {
  static int Assertions;static readonly List<string> Cases=new();
  static void Check(bool ok,string why){Assertions++;if(!ok)throw new Exception(why);}
  static void Test(string name,Action body)
  {
   try{PopupManager.Dismiss();NativeBlackmailNotices.Clear();NativeBlackmail.Clear();NativeGameStateEnvelope.Values.Clear();NativeRegroupSession.Owned.Clear();NativeRegroupSession.Enabled=true;RecruitmentHooks.Registered=true;GameManager.Viewing=true;HotSeatOverlay.IsActive=false;Fault.At="";PopupManager.Shows=PopupManager.Hides=0;PopupManager.IgnoreShow=false;PopupManager.Pool=new();PopupManager.BeforeShow=PopupManager.DuringBuild=null;UnityEngine.PlayerPrefs.Values.Clear();UnityEngine.PlayerPrefs.Reads=UnityEngine.PlayerPrefs.Saves=0;UnityEngine.PlayerPrefs.OnRead=null;ClientPlayerExtensions.Names=new(){[1]="Imperius",[3]="Cymanti",[4]="Elyrion"};Entry.Errors.Clear();body();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}
  }
  static GameState Make(int count=1)
  {
   var s=new GameState{CurrentPlayer=2};s.Players.AddRange(new byte[]{1,2,3,4}.Select(id=>new PlayerState{Id=id}));
   var d=new TileData{coordinates=new(2,3)};s.Map.Tiles.Add(d);var tile=new Tile{Data=d};var map=new MapRenderer();map.Tiles.Add(tile);MapRenderer.Current=map;GameManager.GameState=s;GameManager.Client=new(){GameState=s};GameManager.LocalPlayer=P(s,2);
   var rows=new byte[]{1,3,4}.Take(count).Select((id,i)=>new LedgerBlackmail(id,2,2,3,4,UnitId:(ulong)i+1,LastAppliedTurn:4)).ToArray();
   var units=rows.Select((r,i)=>new LedgerUnit(r.UnitId,(uint)i+1,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,2)).ToArray();
   foreach(var row in units){var body=new UnitState{id=row.NativeId,owner=2,home=new(2,3),coordinates=new(6+(int)row.NativeId,3)};s.Map.Tiles.Add(new TileData{City=false,coordinates=body.coordinates,unit=body});}
   var receipts=rows.Select((r,i)=>Receipt((ulong)i+1,r.Blackmailer,r.X,r.Y,r.UnitId)).ToArray();
   Write(s,new NativeIdentityLedger(Guid.Parse("22694165-90d7-40e9-bac4-de83c2b183a8"),(ulong)count+1,(ulong)count+1,units,receipts,Blackmails:rows),count);NativeRegroupSession.Owned.Add(s);return s;
  }
  static LedgerReceipt Receipt(ulong seq,byte actor,int x,int y,ulong unit=1)=>new(seq,new Guid((int)seq,0,0,new byte[8]),new byte[32],(long)seq-1,(long)seq,new[]{unit});
  static PlayerState P(GameState s,byte id)=>s.Players.Single(p=>p.Id==id);static TileData D(GameState s)=>s.Map.Tiles[0];
  static NativeGameStateEnvelope.Snapshot Snap(GameState s)=>NativeGameStateEnvelope.Get(s)!;
  static NativeIdentityLedger Read(GameState s)=>NativeIdentityLedgerCodec.Decode(Snap(s).Bytes(),Snap(s).Revision);
  static void Write(GameState s,NativeIdentityLedger ledger,long? rev=null){long r=rev??Snap(s).Revision;NativeGameStateEnvelope.Set(s,r,NativeIdentityLedgerCodec.Encode(ledger,r));}
  static void Tick()=>NativeBlackmailNotices.Tick();static void Dismiss()=>PopupManager.Dismiss();
  static string Key(GameState s,long turn=4)=>$"deception.blackmail.notice.v2.{Read(s).Epoch:N}.2.1.1.{turn}";
  public static int Run(){try{
   Test("NOTICE-001-safe-update-only-hook",()=>{var h=new HarmonyLib.Harmony();NativeBlackmailNotices.Install(h);Check(h.Hooks.SequenceEqual(new[]{"GameManager.Update"}),"only reference receiver/no-argument Update hook");});
   Test("NOTICE-002-ready-victim-turn-shows-native-popup",()=>{var s=Make();var snap=Snap(s);Tick();Check(PopupManager.Shows==1&&PopupManager.Current is BasicPopup,"native BasicPopup shown");Check(PopupManager.Pool.Header=="Blackmailed!"&&PopupManager.Pool.Description=="A unit supported by Bardur City is being blackmailed by Imperius. It diverts 1 star per turn from Bardur City to Imperius until the Blackmail ends.","names and exact one-star relationship explained");Check(UnityEngine.PlayerPrefs.Values.GetValueOrDefault(Key(s))==1&&UnityEngine.PlayerPrefs.Saves==1,"UI acknowledgment durable only after showing");Check(ReferenceEquals(snap,Snap(s))&&s.Players.All(p=>p.Currency==20)&&s.ActionStack.Count==0,"popup no authoritative state/money/contact changes");});
   Test("NOTICE-003-duplicate-frames-and-later-turns-once",()=>{var s=Make();Tick();Tick();Dismiss();Tick();s.CurrentTurn++;Tick();Check(PopupManager.Shows==1,"current or acknowledged relationship not repeated");});
   Test("NOTICE-004-reload-retains-playerpref-ack",()=>{var s=Make();Tick();Dismiss();NativeBlackmailNotices.Clear();Write(s,Read(s));Tick();Check(PopupManager.Shows==1,"new snapshot and cleared runtime cache still suppressed by PlayerPrefs");});
   Test("NOTICE-005-each-blackmailer-city-relationship",()=>{Make(3);Tick();Check(PopupManager.Pool.Description.Contains("Imperius"),"canonical first actor");Dismiss();Tick();Check(PopupManager.Pool.Description.Contains("Cymanti"),"next actor only after dismissal");Dismiss();Tick();Check(PopupManager.Pool.Description.Contains("Elyrion")&&PopupManager.Shows==3,"three separate relationships");Dismiss();Tick();Check(PopupManager.Shows==3,"each once");});
   Test("NOTICE-006-loss-of-sight-does-not-clear-notice",()=>{var s=Make();D(s).Visible.Clear();MapRenderer.Current!.Tiles[0].IsHidden=true;Tick();Check(PopupManager.Shows==1,"ongoing owner relation visible to owner despite blackout/fog");});
   foreach(string guard in new[]{"other-turn","other-viewer","zero-viewer","spectating","replay","recap","reaction-recap","processing","queued-action","waiting-command","unready","cover","not-viewing","client-state","inactive-map","dead-map","session","disabled","registry","ended","no-client","no-player","no-snapshot"})
    Test("NOTICE-007-defer-"+guard,()=>{var s=Make();switch(guard){case"other-turn":s.CurrentPlayer=1;break;case"other-viewer":GameManager.LocalPlayer=P(s,1);break;case"zero-viewer":GameManager.LocalPlayer=new();s.CurrentPlayer=0;break;case"spectating":GameManager.Client!.IsSpectating=true;break;case"replay":GameManager.Client!.IsReplay=true;break;case"recap":GameManager.Client!.IsRecap=true;break;case"reaction-recap":GameManager.Client!.ActionManager.IsRecap=true;break;case"processing":GameManager.Client!.ActionManager.IsProcessing=true;break;case"queued-action":s.ActionStack.Add(new());break;case"waiting-command":GameManager.Client!.IsWaitingForCommand=true;break;case"unready":GameManager.Client!.IsReady=false;break;case"cover":HotSeatOverlay.IsActive=true;break;case"not-viewing":GameManager.Viewing=false;break;case"client-state":GameManager.Client!.GameState=new();break;case"inactive-map":MapRenderer.Current!.gameObject.SetActive(false);break;case"dead-map":MapRenderer.Current!.Dead=true;break;case"session":NativeRegroupSession.Owned.Clear();break;case"disabled":NativeRegroupSession.Enabled=false;break;case"registry":RecruitmentHooks.Registered=false;break;case"ended":s.CurrentState=GameState.State.Ended;break;case"no-client":GameManager.Client=null;break;case"no-player":GameManager.LocalPlayer=null;break;case"no-snapshot":NativeGameStateEnvelope.Values.Remove(s);break;}Tick();Check(PopupManager.Shows==0&&UnityEngine.PlayerPrefs.Values.Count==0,"invalid or unready context neither shows nor acknowledges");});
   Test("NOTICE-008-waits-native-popup-and-reactions",()=>{var s=Make();PopupManager.Current=new BasicPopup{Header="Meet"};PopupManager.PopupShowing=true;Tick();Check(PopupManager.Shows==0&&PopupManager.Current.Header=="Meet","native meeting first");Dismiss();GameManager.Client!.ActionManager.IsProcessing=true;Tick();GameManager.Client.ActionManager.IsProcessing=false;s.ActionStack.Add(new());Tick();Check(PopupManager.Shows==0,"all child actions drain first");s.ActionStack.Clear();Tick();Check(PopupManager.Shows==1,"ready turn eventually shows");});
   foreach(string gone in new[]{"captured","destroyed","victim-dead","actor-dead","actor-missing","row-removed"})Test("NOTICE-009-cleared-"+gone,()=>{var s=Make();switch(gone){case"captured":D(s).owner=3;break;case"destroyed":D(s).City=false;break;case"victim-dead":P(s,2).Alive=false;break;case"actor-dead":P(s,1).Alive=false;break;case"actor-missing":s.Players.Remove(P(s,1));break;case"row-removed":Write(s,Read(s)with{Blackmails=Array.Empty<LedgerBlackmail>()});break;}Tick();Check(PopupManager.Shows==0&&UnityEngine.PlayerPrefs.Values.Count==0,"inactive relation not disclosed");});
   Test("NOTICE-010-new-unit-layer-turn-is-new-event",()=>{var s=Make();Tick();Dismiss();var l=Read(s);l=l with{NextSequence=3,Receipts=l.Receipts.Append(Receipt(2,1,2,3)).ToArray(),Blackmails=l.Blackmails!.Select(r=>r with{Layers=2,LastAppliedTurn=5}).ToArray()};Write(s,l,2);Tick();Check(PopupManager.Shows==2&&UnityEngine.PlayerPrefs.Values.Count==2,"new layer same actor and unit has distinct purchase turn identity");});
   Test("NOTICE-011-new-match-epoch-not-old-ack",()=>{var s=Make();Tick();Dismiss();Write(s,Read(s)with{Epoch=Guid.NewGuid()});Tick();Check(PopupManager.Shows==2,"different match gets its own notice");});
   Test("NOTICE-012-payout-snapshot-keeps-same-event",()=>{var s=Make();Tick();Dismiss();Write(s,Read(s)with{Blackmails=Read(s).Blackmails!.Select(r=>r with{LastPaidTurn=4}).ToArray()});Tick();Check(PopupManager.Shows==1,"LastPaidTurn does not create another notice");});
   Test("NOTICE-013-unit-purchase-stamp-independent-of-receipt-kind",()=>{var s=Make();Write(s,Read(s)with{NextSequence=1,Receipts=Array.Empty<LedgerReceipt>()});Tick();Check(PopupManager.Shows==1&&UnityEngine.PlayerPrefs.Values.Count==1,"validated unit purchase stamp identifies notice without ambiguous generic receipts");});
   Test("NOTICE-014-city-and-localized-tribe-name-plain-text",()=>{var s=Make();D(s).improvement.name="A <color=red>City</color>\nB";ClientPlayerExtensions.Names[1]="Die Imperius";Tick();Check(PopupManager.Pool.Description.Contains("A ‹color=red›City‹/color› B")&&PopupManager.Pool.Description.Contains("Die Imperius"),"native localized tribe retained and city cannot inject rich text");});
   foreach(string phase in new[]{"factory","header","description","buttons","show-before","show-after","prefs-write"})Test("NOTICE-015-popup-failure-"+phase,()=>{var s=Make();Fault.At=phase;Tick();Check(UnityEngine.PlayerPrefs.Values.Count==0&&Entry.Errors.Count>0,"failed display does not acknowledge");Check(!PopupManager.PopupShowing,"partially shown owned popup hidden");Tick();Check(PopupManager.PopupShowing&&UnityEngine.PlayerPrefs.Values.Count==1,"failure may retry on ready frame");});
   Test("NOTICE-016-show-did-not-become-current-not-acknowledged",()=>{Make();PopupManager.IgnoreShow=true;Tick();Check(UnityEngine.PlayerPrefs.Values.Count==0&&!PopupManager.PopupShowing,"no successful show means no ack");PopupManager.IgnoreShow=false;Tick();Check(PopupManager.Shows==1,"can retry");});
   foreach(string phase in new[]{"construction","show"})foreach(string stale in new[]{"viewer","map","state-map","turn","snapshot","capture","generation"})Test("NOTICE-017-stale-"+phase+"-"+stale,()=>{var s=Make();Action change=()=>{switch(stale){case"viewer":GameManager.LocalPlayer=P(s,1);break;case"map":MapRenderer.Current=new();break;case"state-map":s.Map=new();break;case"turn":s.CurrentTurn++;break;case"snapshot":Write(s,Read(s));break;case"capture":D(s).owner=3;break;case"generation":NativeBlackmailNotices.Clear();break;}};if(phase=="construction")PopupManager.DuringBuild=change;else PopupManager.BeforeShow=change;Tick();Check(UnityEngine.PlayerPrefs.Values.Count==0&&!PopupManager.PopupShowing,"stale mid-show context cannot leave notice or acknowledge");});
   Test("NOTICE-018-hotseat-switch-hides-exact-owned-popup",()=>{var s=Make();Tick();HotSeatOverlay.IsActive=true;Tick();Check(!PopupManager.PopupShowing&&PopupManager.Hides==1,"private turn notice retired before another viewer");});
   Test("NOTICE-019-pool-reuse-never-hides-foreign-content",()=>{var s=Make();Tick();PopupManager.Pool.Header="Native Help";PopupManager.Pool.buttonData=new();GameManager.LocalPlayer=P(s,1);Tick();Check(PopupManager.PopupShowing&&PopupManager.Hides==0,"same pooled object with new content belongs to native UI");NativeBlackmailNotices.Clear();Check(PopupManager.PopupShowing,"Clear cannot destroy foreign popup");});
   Test("NOTICE-020-clear-retires-owned-popup-only",()=>{Make();Tick();NativeBlackmailNotices.Clear();Check(!PopupManager.PopupShowing&&PopupManager.Hides==1,"exact owned popup hidden without destruction");Check(UnityEngine.PlayerPrefs.Values.Count==1,"persistent acknowledgment retained");});
   Test("NOTICE-021-reentrant-frame-cannot-double-show",()=>{Make();PopupManager.DuringBuild=Tick;PopupManager.BeforeShow=Tick;Tick();Check(PopupManager.Shows==1&&UnityEngine.PlayerPrefs.Values.Count==1,"recursive Update is bounded");});
   Test("NOTICE-022-immutable-snapshot-decode-cache",()=>{var s=Make();var snap=Snap(s);Tick();Dismiss();int reads=snap.Reads;int prefs=UnityEngine.PlayerPrefs.Reads;for(int i=0;i<100;i++)Tick();Check(snap.Reads==reads&&UnityEngine.PlayerPrefs.Reads==prefs,"idle acknowledged relationship does not decode history or reread preferences per frame");});
   Test("NOTICE-023-failed-hide-retains-exact-token-for-retry",()=>{Make();Tick();Fault.At="hide-before";NativeBlackmailNotices.Clear();Check(PopupManager.PopupShowing&&PopupManager.Hides==0,"failed native Hide does not fake successful cleanup");Tick();Check(!PopupManager.PopupShowing&&PopupManager.Hides==1,"retained stale generation token retries exact popup cleanup");});
   Test("NOTICE-024-hide-throw-after-close-does-not-touch-reused-popup",()=>{Make();Tick();Fault.At="hide-after";NativeBlackmailNotices.Clear();PopupManager.Pool.Header="Native";PopupManager.Pool.buttonData=new();PopupManager.Current=PopupManager.Pool;PopupManager.PopupShowing=true;Tick();Check(PopupManager.PopupShowing&&PopupManager.Hides==1,"already closed token cannot retire new native ownership");});
   Test("NOTICE-025-unrelated-unit-receipt-cannot-repeat-purchase",()=>{var s=Make();Tick();Dismiss();var l=Read(s);Write(s,l with{NextSequence=3,Receipts=l.Receipts.Append(Receipt(2,1,2,3)).ToArray()},2);Tick();Check(PopupManager.Shows==1&&UnityEngine.PlayerPrefs.Values.Count==1,"Regroup or Shed receipt touching the target cannot masquerade as Blackmail");});
   Test("NOTICE-026-stacked-income-copy-and-capped-effective-layers",()=>{var s=Make();var l=Read(s);Write(s,l with{Blackmails=l.Blackmails!.Select(r=>r with{Layers=4,LastAppliedTurn=5}).ToArray()});D(s).Income=2;Tick();Check(PopupManager.Shows==1&&PopupManager.Pool.Description.Contains("diverts 2 stars per turn"),"notice remains tied to contract identity while its effective income is capped");});
   Test("NOTICE-027-legacy-city-only-record-not-announced",()=>{var s=Make();var row=new LedgerBlackmail(1,2,2,3,4);var receipt=new LedgerReceipt(1,new Guid(1,0,0,new byte[8]),new byte[32],0,1,Array.Empty<ulong>(),new(1,2,3));Write(s,Read(s)with{Receipts=new[]{receipt},Blackmails=new[]{row}});Tick();Check(PopupManager.Shows==0&&UnityEngine.PlayerPrefs.Values.Count==0,"obsolete city lien has no unit and cannot generate a current notice");});
   Test("NOTICE-028-unit-death-clears-pending-notice",()=>{var s=Make();s.Map.Tiles[1].unit=null;Tick();Check(PopupManager.Shows==0&&UnityEngine.PlayerPrefs.Values.Count==0,"dead target stops lien even before ledger retirement is reconciled");});
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,scope="Production notice, Blackmail adapter and NativeApi against synthetic native UI/persistence ports; no native gameplay claim"}));return 0;
  }catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{passed=false,cases=Cases.Count,assertions=Assertions,error=e.ToString()}));return 1;}}
 }
}
